     *   ↓           ↓       ↓ [uint32]: value after (duration)
     * 0xAAAAAAAAAAAABBBBBBBBCCCCCCCC
     * ```
     *
     * NOTE: The {get} and {withUpdate} functions operate using timestamps. Block number based delays are not currently
     * supported.
     */
    type Delay is uint112;

    /**
     * @dev Wrap a duration into a Delay to add the one-step "update in the future" feature
     */
    function toDelay(uint32 duration) internal pure returns (Delay) {
        return Delay.wrap(duration);
    }

    /**
     * @dev Get the value at a given timepoint plus the pending value and effect timepoint if there is a scheduled
     * change after this timepoint. If the effect timepoint is 0, then the pending value should not be considered.
     */
    function _getFullAt(
        Delay self,
        uint48 timepoint
    ) private pure returns (uint32 valueBefore, uint32 valueAfter, uint48 effect) {
        (valueBefore, valueAfter, effect) = self.unpack();
        return effect <= timepoint ? (valueAfter, 0, 0) : (valueBefore, valueAfter, effect);
    }

    /**
     * @dev Get the current value plus the pending value and effect timepoint if there is a scheduled change. If the
     * effect timepoint is 0, then the pending value should not be considered.
     */
    function getFull(Delay self) internal view returns (uint32 valueBefore, uint32 valueAfter, uint48 effect) {
        return _getFullAt(self, timestamp());
    }

    /**
     * @dev Get the current value.
     */
    function get(Delay self) internal view returns (uint32) {
        (uint32 delay, , ) = self.getFull();
        return delay;
    }

    /**
     * @dev Update a Delay object so that it takes a new duration after a timepoint that is automatically computed to
     * enforce the old delay at the moment of the update. Returns the updated Delay object and the timestamp when the
     * new delay becomes effective.
     */
    function withUpdate(
        Delay self,
        uint32 newValue,
        uint32 minSetback
    ) internal view returns (Delay updatedDelay, uint48 effect) {
        uint32 value = self.get();
        uint32 setback = uint32(Math.max(minSetback, value > newValue ? value - newValue : 0));
        effect = timestamp() + setback;
        return (pack(value, newValue, effect), effect);
    }

    /**
     * @dev Split a delay into its components: valueBefore, valueAfter and effect (transition timepoint).
     */
    function unpack(Delay self) internal pure returns (uint32 valueBefore, uint32 valueAfter, uint48 effect) {
        uint112 raw = Delay.unwrap(self);

        valueAfter = uint32(raw);
        valueBefore = uint32(raw >> 32);
        effect = uint48(raw >> 64);

        return (valueBefore, valueAfter, effect);
    }

    /**
     * @dev pack the components into a Delay object.
     */
    function pack(uint32 valueBefore, uint32 valueAfter, uint48 effect) internal pure returns (Delay) {
        return Delay.wrap((uint112(effect) << 64) | (uint112(valueBefore) << 32) | uint112(valueAfter));
    }
}

contracts/NYAXGovernor.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/governance/Governor.sol";
import "@openzeppelin/contracts/governance/extensions/GovernorSettings.sol";
import "@openzeppelin/contracts/governance/extensions/GovernorCountingSimple.sol";
import "@openzeppelin/contracts/governance/extensions/GovernorVotes.sol";
import "@openzeppelin/contracts/governance/extensions/GovernorVotesQuorumFraction.sol";
import "@openzeppelin/contracts/governance/extensions/GovernorTimelockControl.sol";
import "@openzeppelin/contracts/governance/TimelockController.sol";

/**
 * @title NYAXGovernor
 * @dev OpenZeppelin Governor implementation for NYAX Platform governance
 * 
 * Features:
 * - Proposal creation and voting
 * - Timelock execution for security
 * - Quorum-based decision making
 * - Vote delegation support
 * - Emergency fast-track procedures
 */
contract NYAXGovernor is
    Governor,
    GovernorSettings,
    GovernorCountingSimple,
    GovernorVotes,
    GovernorVotesQuorumFraction,
    GovernorTimelockControl
{
    // Custom events
    event EmergencyProposalCreated(uint256 proposalId, string description);
    event FastTrackEnabled(uint256 proposalId);

    // Emergency governance
    mapping(uint256 => bool) public emergencyProposals;
    mapping(uint256 => bool) public fastTrackEnabled;

    // Proposal metadata
    mapping(uint256 => address) private _proposalCreators;

    // Constants
    uint256 public constant EMERGENCY_VOTING_DELAY = 1; // 1 block
    uint256 public constant EMERGENCY_VOTING_PERIOD = 50400; // ~1 week
    uint256 public constant EMERGENCY_QUORUM = 10; // 10% for emergency proposals

    /**
     * @dev Constructor
     * @param _token NYAX token address (must implement IVotes)
     * @param _timelock Timelock controller address
     * @param _votingDelay Delay before voting starts (in blocks)
     * @param _votingPeriod Duration of voting period (in blocks)
     * @param _proposalThreshold Minimum tokens needed to create proposal
     * @param _quorumPercentage Percentage of total supply needed for quorum
     */
    constructor(
        IVotes _token,
        TimelockController _timelock,
        uint48 _votingDelay,
        uint32 _votingPeriod,
        uint256 _proposalThreshold,
        uint256 _quorumPercentage
    )
        Governor("NYAXGovernor")
        GovernorSettings(_votingDelay, _votingPeriod, _proposalThreshold)
        GovernorVotes(_token)
        GovernorVotesQuorumFraction(_quorumPercentage)
        GovernorTimelockControl(_timelock)
    {}

    /**
     * @dev Create an emergency proposal with reduced delays
     * @param targets Array of target addresses
     * @param values Array of ETH values
     * @param calldatas Array of function call data
     * @param description Proposal description
     * @return proposalId The ID of the created proposal
     */
    function proposeEmergency(
        address[] memory targets,
        uint256[] memory values,
        bytes[] memory calldatas,
        string memory description
    ) public returns (uint256 proposalId) {
        // Check if caller has enough tokens for emergency proposals
        require(
            getVotes(msg.sender, block.number - 1) >= proposalThreshold(),
            "NYAXGovernor: proposer votes below proposal threshold"
        );

        proposalId = propose(targets, values, calldatas, description);
        emergencyProposals[proposalId] = true;

        emit EmergencyProposalCreated(proposalId, description);
        return proposalId;
    }

    /**
     * @dev Override propose to capture proposer addresses
     */
    function propose(
        address[] memory targets,
        uint256[] memory values,
        bytes[] memory calldatas,
        string memory description
    ) public override returns (uint256 proposalId) {
        proposalId = super.propose(targets, values, calldatas, description);
        _proposalCreators[proposalId] = _msgSender();
    }

    /**
     * @dev Enable fast-track execution for critical proposals
     * @param proposalId The proposal ID to fast-track
     */
    function enableFastTrack(uint256 proposalId) external onlyGovernance {
        require(state(proposalId) == ProposalState.Succeeded, "NYAXGovernor: proposal not succeeded");
        fastTrackEnabled[proposalId] = true;
        emit FastTrackEnabled(proposalId);
    }

    /**
     * @dev Override voting delay for emergency proposals
     */
    function proposalDeadline(uint256 proposalId) public view override(Governor) returns (uint256) {
        if (emergencyProposals[proposalId]) {
            return proposalSnapshot(proposalId) + EMERGENCY_VOTING_PERIOD;
        }
        return super.proposalDeadline(proposalId);
    }

    /**
     * @dev Override voting delay for emergency proposals
     */
    function votingDelay() public view override(Governor, GovernorSettings) returns (uint256) {
        return super.votingDelay();
    }

    /**
     * @dev Override voting period
     */
    function votingPeriod() public view override(Governor, GovernorSettings) returns (uint256) {
        return super.votingPeriod();
    }

    /**
     * @dev Override quorum for emergency proposals
     */
    function quorum(uint256 blockNumber) public view override(Governor, GovernorVotesQuorumFraction) returns (uint256) {
        return super.quorum(blockNumber);
    }

    /**
     * @dev Custom quorum calculation for emergency proposals
     */
    function _quorumReached(uint256 proposalId) internal view override(Governor, GovernorCountingSimple) returns (bool) {
        if (emergencyProposals[proposalId]) {
            (uint256 againstVotes, uint256 forVotes, uint256 abstainVotes) = proposalVotes(proposalId);
            uint256 totalVotes = againstVotes + forVotes + abstainVotes;
            uint256 emergencyQuorumVotes = (token().getPastTotalSupply(proposalSnapshot(proposalId)) * EMERGENCY_QUORUM) / 100;
            return totalVotes >= emergencyQuorumVotes;
        }
        return super._quorumReached(proposalId);
    }

    /**
     * @dev Override proposal threshold
     */
    function proposalThreshold() public view override(Governor, GovernorSettings) returns (uint256) {
        return super.proposalThreshold();
    }

    /**
     * @dev Override state function to handle fast-track
     */
    function state(uint256 proposalId) public view override(Governor, GovernorTimelockControl) returns (ProposalState) {
        ProposalState currentState = super.state(proposalId);

        // If fast-track is enabled and proposal succeeded, it can be executed immediately
        if (fastTrackEnabled[proposalId] && currentState == ProposalState.Queued) {
            return ProposalState.Succeeded;
        }

        return currentState;
    }

    /**
     * @dev Skip queuing for fast-track proposals
     */
    function proposalNeedsQueuing(uint256 proposalId)
        public
        view
        override(Governor, GovernorTimelockControl)
        returns (bool)
    {
        if (fastTrackEnabled[proposalId]) {
            return false;
        }
        return super.proposalNeedsQueuing(proposalId);
    }

    /**
     * @dev Override queue operations to bypass timelock when fast-track is enabled
     */
    function _queueOperations(
        uint256 proposalId,
        address[] memory targets,
        uint256[] memory values,
        bytes[] memory calldatas,
        bytes32 descriptionHash
    ) internal override(Governor, GovernorTimelockControl) returns (uint48) {
        if (fastTrackEnabled[proposalId]) {
            // Return 0 to indicate immediate availability
            return 0;
        }
        return super._queueOperations(proposalId, targets, values, calldatas, descriptionHash);
    }

    /**
     * @dev Override execute operations to handle fast-track execution
     */
    function _executeOperations(
        uint256 proposalId,
        address[] memory targets,
        uint256[] memory values,
        bytes[] memory calldatas,
        bytes32 descriptionHash
    ) internal override(Governor, GovernorTimelockControl) {
        if (fastTrackEnabled[proposalId]) {
            for (uint256 i = 0; i < targets.length; ++i) {
                _executeDirectCall(targets[i], values[i], calldatas[i]);
            }
        } else {
            super._executeOperations(proposalId, targets, values, calldatas, descriptionHash);
        }
    }

    /**
     * @dev Override _cancel to handle timelock
     */
    function _cancel(
        address[] memory targets,
        uint256[] memory values,
        bytes[] memory calldatas,
        bytes32 descriptionHash
    ) internal override(Governor, GovernorTimelockControl) returns (uint256) {
        return super._cancel(targets, values, calldatas, descriptionHash);
    }

    /**
     * @dev Override _executor to return timelock address
     */
    function _executor() internal view override(Governor, GovernorTimelockControl) returns (address) {
        return super._executor();
    }

    /**
     * @dev Check if proposal is emergency proposal
     */
    function isEmergencyProposal(uint256 proposalId) external view returns (bool) {
        return emergencyProposals[proposalId];
    }

    /**
     * @dev Check if fast-track is enabled for proposal
     */
    function isFastTrackEnabled(uint256 proposalId) external view returns (bool) {
        return fastTrackEnabled[proposalId];
    }

    /**
     * @dev Get proposal details including emergency status
     */
    function getProposalDetails(uint256 proposalId) external view returns (
        address proposer,
        uint256 eta,
        uint256 startBlock,
        uint256 endBlock,
        uint256 forVotes,
        uint256 againstVotes,
        uint256 abstainVotes,
        bool isEmergency,
        bool isFastTrack,
        ProposalState currentState
    ) {
        proposer = _proposalCreators[proposalId];
        eta = proposalEta(proposalId);
        startBlock = proposalSnapshot(proposalId);
        endBlock = proposalDeadline(proposalId);
        (againstVotes, forVotes, abstainVotes) = proposalVotes(proposalId);
        isEmergency = emergencyProposals[proposalId];
        isFastTrack = fastTrackEnabled[proposalId];
        currentState = state(proposalId);
    }

    function _executeDirectCall(address target, uint256 value, bytes memory data) private {
        (bool success, bytes memory returndata) = target.call{value: value}(data);
        if (!success) {
            if (returndata.length > 0) {
                /// @solidity memory-safe-assembly
                assembly {
                    revert(add(returndata, 32), mload(returndata))
                }
            } else {
                revert("NYAXGovernor: fast-track execution failed");
            }
        }
    }
}

/**
 * @title NYAXTimelockController
 * @dev Custom timelock controller for NYAX governance
 */
contract NYAXTimelockController is TimelockController {
    /**
     * @dev Constructor
     * @param minDelay Minimum delay for operations
     * @param proposers Array of proposer addresses
     * @param executors Array of executor addresses
     * @param admin Admin address (can be zero address to renounce)
     */
    constructor(
        uint256 minDelay,
        address[] memory proposers,
        address[] memory executors,
        address admin
    ) TimelockController(minDelay, proposers, executors, admin) {}

    /**
     * @dev Emergency execution function (only for critical situations)
     * @param target Target contract address
     * @param value ETH value to send
     * @param data Function call data
     */
    function emergencyExecute(
        address target,
        uint256 value,
        bytes calldata data
    ) external onlyRole(EXECUTOR_ROLE) {
        (bool success, ) = target.call{value: value}(data);
        require(success, "NYAXTimelockController: emergency execution failed");
    }
}

contracts/NYAXToken.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Permit.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Votes.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title NYAXToken
 * @dev NYAX token with governance capabilities, permit functionality, and controlled minting
 */
contract NYAXToken is ERC20, ERC20Permit, ERC20Votes, Ownable, ReentrancyGuard {

    uint256 public constant MAX_SUPPLY = 1_000_000_000 * 10**18;

    address public treasury;
    bool public transfersEnabled = true;
    mapping(address => bool) public blacklisted;

    event TreasuryUpdated(address indexed oldTreasury, address indexed newTreasury);
    event TransfersToggled(bool enabled);
    event AddressBlacklisted(address indexed account, bool blacklisted);
    event TokensMinted(address indexed to, uint256 amount);
    event TokensBurned(address indexed from, uint256 amount);

    modifier onlyTreasuryOrOwner() {
        require(msg.sender == treasury || msg.sender == owner(), "Not authorized");
        _;
    }

    modifier whenTransfersEnabled() {
        require(transfersEnabled, "Transfers disabled");
        _;
    }

    modifier notBlacklisted(address account) {
        require(!blacklisted[account], "Blacklisted");
        _;
    }

    constructor(address _treasury, address _owner)
        ERC20("NYAX", "NYAX")
        ERC20Permit("NYAX")
        Ownable(_owner)
    {
        require(_treasury != address(0), "Treasury zero address");
        treasury = _treasury;
        emit TreasuryUpdated(address(0), _treasury);
    }

    function setTreasury(address _treasury) external onlyOwner {
        require(_treasury != address(0), "Zero");
        address old = treasury;
        treasury = _treasury;
        emit TreasuryUpdated(old, _treasury);
    }

    function mint(address to, uint256 amount) external onlyTreasuryOrOwner nonReentrant {
        require(totalSupply() + amount <= MAX_SUPPLY, "Exceeds max supply");
        _mint(to, amount);
        emit TokensMinted(to, amount);
    }

    function burn(address from, uint256 amount) external onlyTreasuryOrOwner nonReentrant {
        _burn(from, amount);
        emit TokensBurned(from, amount);
    }

    function burnSelf(uint256 amount) external nonReentrant {
        _burn(msg.sender, amount);
        emit TokensBurned(msg.sender, amount);
    }

    function setTransfersEnabled(bool enabled) external onlyOwner {
        transfersEnabled = enabled;
        emit TransfersToggled(enabled);
    }

    function setBlacklisted(address account, bool isBlacklisted) external onlyOwner {
        blacklisted[account] = isBlacklisted;
        emit AddressBlacklisted(account, isBlacklisted);
    }

    function batchSetBlacklisted(address[] calldata accounts, bool isBlacklisted)
        external
        onlyOwner
    {
        for (uint256 i = 0; i < accounts.length; i++) {
            blacklisted[accounts[i]] = isBlacklisted;
            emit AddressBlacklisted(accounts[i], isBlacklisted);
        }
    }

    function remainingMintableSupply() external view returns (uint256) {
        return MAX_SUPPLY - totalSupply();
    }

    function nonces(address owner)
    public
    view
    override(ERC20Permit, Nonces)
    returns (uint256)
    {
    return super.nonces(owner);
    }


    function _update(address from, address to, uint256 amount)
        internal
        override(ERC20, ERC20Votes)
    {
        require(!blacklisted[from] && !blacklisted[to], "Blacklisted");
        require(transfersEnabled || from == address(0) || to == address(0), "Transfers disabled");

        super._update(from, to, amount);
    }

    // Recover ERC20 tokens
    function recoverERC20(address token, uint256 amount) external onlyOwner {
        require(token != address(this), "Cannot recover NYAX itself");
        IERC20(token).transfer(owner(), amount);
    }

    // Recover ETH
    function recoverETH() external onlyOwner {
        payable(owner()).transfer(address(this).balance);
    }
}

contracts/SimpleMultiSig.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title SimpleMultiSig
 * @dev A simple multi-signature wallet for NYAX Treasury operations
 * 
 * Features:
 * - Multiple owners with configurable threshold
 * - Transaction submission, confirmation, and execution
 * - Support for ETH and ERC20 token transfers
 * - Emergency functions
 * - Owner management
 * 
 * Note: For production, consider using Gnosis Safe instead
 */
contract SimpleMultiSig is ReentrancyGuard {

    // Events
    event OwnerAdded(address indexed owner);
    event OwnerRemoved(address indexed owner);
    event ThresholdChanged(uint256 threshold);
    event TransactionSubmitted(uint256 indexed txIndex, address indexed to, uint256 value, bytes data);
    event TransactionConfirmed(address indexed owner, uint256 indexed txIndex);
    event TransactionRevoked(address indexed owner, uint256 indexed txIndex);
    event TransactionExecuted(uint256 indexed txIndex);
    event Deposit(address indexed sender, uint256 amount, uint256 balance);

    // State variables
    uint256 public threshold;
    address[] public owners;
    mapping(address => bool) public isOwner;
    uint256 public transactionCount;

    struct Transaction {
        address to;
        uint256 value;
        bytes data;
        bool executed;
        uint256 confirmations;
        mapping(address => bool) isConfirmed;
    }

    mapping(uint256 => Transaction) public transactions;

    // Modifiers
    modifier onlyOwner() {
        require(isOwner[msg.sender], "SimpleMultiSig: Not an owner");
        _;
    }

    modifier txExists(uint256 txIndex) {
        require(txIndex < transactionCount, "SimpleMultiSig: Transaction does not exist");
        _;
    }

    modifier notExecuted(uint256 txIndex) {
        require(!transactions[txIndex].executed, "SimpleMultiSig: Transaction already executed");
        _;
    }

    modifier notConfirmed(uint256 txIndex) {
        require(!transactions[txIndex].isConfirmed[msg.sender], "SimpleMultiSig: Transaction already confirmed");
        _;
    }

    /**
     * @dev Constructor
     * @param _owners Array of owner addresses
     * @param _threshold Number of confirmations required
     */
    constructor(address[] memory _owners, uint256 _threshold) {
        require(_owners.length > 0, "SimpleMultiSig: Owners required");
        require(
            _threshold > 0 && _threshold <= _owners.length,
            "SimpleMultiSig: Invalid threshold"
        );

        for (uint256 i = 0; i < _owners.length; i++) {
            address owner = _owners[i];
            require(owner != address(0), "SimpleMultiSig: Invalid owner address");
            require(!isOwner[owner], "SimpleMultiSig: Duplicate owner");

            isOwner[owner] = true;
            owners.push(owner);
            emit OwnerAdded(owner);
        }

        threshold = _threshold;
        emit ThresholdChanged(_threshold);
    }

    /**
     * @dev Receive function to accept ETH deposits
     */
    receive() external payable {
        emit Deposit(msg.sender, msg.value, address(this).balance);
    }

    /**
     * @dev Submit a new transaction
     * @param to Destination address
     * @param value ETH value to send
     * @param data Transaction data
     * @return txIndex Index of the submitted transaction
     */
    function submitTransaction(
        address to,
        uint256 value,
        bytes memory data
    ) public onlyOwner returns (uint256 txIndex) {
        txIndex = transactionCount;

        Transaction storage transaction = transactions[txIndex];
        transaction.to = to;
        transaction.value = value;
        transaction.data = data;
        transaction.executed = false;
        transaction.confirmations = 0;

        transactionCount += 1;

        emit TransactionSubmitted(txIndex, to, value, data);

        // Auto-confirm by submitter
        confirmTransaction(txIndex);

        return txIndex;
    }

    /**
     * @dev Confirm a transaction
     * @param txIndex Transaction index
     */
    function confirmTransaction(uint256 txIndex)
        public
        onlyOwner
        txExists(txIndex)
        notConfirmed(txIndex)
        notExecuted(txIndex)
    {
        Transaction storage transaction = transactions[txIndex];
        transaction.isConfirmed[msg.sender] = true;
        transaction.confirmations += 1;

        emit TransactionConfirmed(msg.sender, txIndex);

        // Auto-execute if threshold is met
        if (transaction.confirmations >= threshold) {
            executeTransaction(txIndex);
        }
    }

    /**
     * @dev Revoke confirmation for a transaction
     * @param txIndex Transaction index
     */
    function revokeConfirmation(uint256 txIndex)
        public
        onlyOwner
        txExists(txIndex)
        notExecuted(txIndex)
    {
        Transaction storage transaction = transactions[txIndex];
        require(transaction.isConfirmed[msg.sender], "SimpleMultiSig: Transaction not confirmed");

        transaction.isConfirmed[msg.sender] = false;
        transaction.confirmations -= 1;

        emit TransactionRevoked(msg.sender, txIndex);
    }

    /**
     * @dev Execute a confirmed transaction
     * @param txIndex Transaction index
     */
    function executeTransaction(uint256 txIndex)
        public
        onlyOwner
        txExists(txIndex)
        notExecuted(txIndex)
        nonReentrant
    {
        Transaction storage transaction = transactions[txIndex];
        require(
            transaction.confirmations >= threshold,
            "SimpleMultiSig: Insufficient confirmations"
        );

        transaction.executed = true;

        (bool success, ) = transaction.to.call{value: transaction.value}(transaction.data);
        require(success, "SimpleMultiSig: Transaction execution failed");

        emit TransactionExecuted(txIndex);
    }

    /**
     * @dev Get transaction details
     * @param txIndex Transaction index
     * @return to Destination address
     * @return value ETH value
     * @return data Transaction data
     * @return executed Whether transaction is executed
     * @return confirmations Number of confirmations
     */
    function getTransaction(uint256 txIndex)
        public
        view
        returns (
            address to,
            uint256 value,
            bytes memory data,
            bool executed,
            uint256 confirmations
        )
    {
        Transaction storage transaction = transactions[txIndex];
        return (
            transaction.to,
            transaction.value,
            transaction.data,
            transaction.executed,
            transaction.confirmations
        );
    }

    /**
     * @dev Check if transaction is confirmed by owner
     * @param txIndex Transaction index
     * @param owner Owner address
     * @return Whether transaction is confirmed by owner
     */
    function isConfirmed(uint256 txIndex, address owner) public view returns (bool) {
        return transactions[txIndex].isConfirmed[owner];
    }

    /**
     * @dev Get all owners
     * @return Array of owner addresses
     */
    function getOwners() public view returns (address[] memory) {
        return owners;
    }

    /**
     * @dev Get number of owners
     * @return Number of owners
     */
    function getOwnerCount() public view returns (uint256) {
        return owners.length;
    }

    /**
     * @dev Get transaction count
     * @return Total number of transactions
     */
    function getTransactionCount() public view returns (uint256) {
        return transactionCount;
    }

    /**
     * @dev Add a new owner (requires multisig approval)
     * @param owner New owner address
     */
    function addOwner(address owner) external {
        require(msg.sender == address(this), "SimpleMultiSig: Only multisig can add owners");
        require(owner != address(0), "SimpleMultiSig: Invalid owner address");
        require(!isOwner[owner], "SimpleMultiSig: Owner already exists");

        isOwner[owner] = true;
        owners.push(owner);
        emit OwnerAdded(owner);
    }

    /**
     * @dev Remove an owner (requires multisig approval)
     * @param owner Owner address to remove
     */
    function removeOwner(address owner) external {
        require(msg.sender == address(this), "SimpleMultiSig: Only multisig can remove owners");
        require(isOwner[owner], "SimpleMultiSig: Not an owner");
        require(owners.length > threshold, "SimpleMultiSig: Cannot remove owner below threshold");

        isOwner[owner] = false;

        // Remove from owners array
        for (uint256 i = 0; i < owners.length; i++) {
            if (owners[i] == owner) {
                owners[i] = owners[owners.length - 1];
                owners.pop();
                break;
            }
        }

        emit OwnerRemoved(owner);
    }

    /**
     * @dev Change the threshold (requires multisig approval)
     * @param _threshold New threshold
     */
    function changeThreshold(uint256 _threshold) external {
        require(msg.sender == address(this), "SimpleMultiSig: Only multisig can change threshold");
        require(
            _threshold > 0 && _threshold <= owners.length,
            "SimpleMultiSig: Invalid threshold"
        );

        threshold = _threshold;
        emit ThresholdChanged(_threshold);
    }

    /**
     * @dev Emergency function to recover stuck ETH (requires multisig approval)
     * @param to Recipient address
     * @param amount Amount to recover
     */
    function emergencyWithdraw(address payable to, uint256 amount) external {
        require(msg.sender == address(this), "SimpleMultiSig: Only multisig can emergency withdraw");
        require(to != address(0), "SimpleMultiSig: Invalid recipient");
        require(amount <= address(this).balance, "SimpleMultiSig: Insufficient balance");

        to.transfer(amount);
    }
}

contracts/Treasury.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "./NYAXToken.sol";
import "./SimpleMultiSig.sol";

/**
 * @title Treasury
 * @dev NYAX Treasury contract for managing token allocations and distributions
 * 
 * Features:
 * - Category-based wallet management
 * - Integration with MultiSig for large transfers
 * - Token minting and burning capabilities
 * - Allocation tracking and limits
 * - Emergency functions
 * - Vesting contract integration
 */
contract Treasury is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // State variables
    NYAXToken public nyax;
    SimpleMultiSig public multisig;

    // Category management
    mapping(string => address) public categoryWallet;
    mapping(string => uint256) public categoryAllocation; // Percentage allocation (basis points)
    mapping(string => uint256) public categoryDistributed; // Amount already distributed
    mapping(string => bool) public categoryExists;
    string[] public categories;

    // Constants
    uint256 public constant BASIS_POINTS = 10000; // 100% = 10000 basis points
    uint256 public constant MULTISIG_THRESHOLD = 1000000 * 10**18; // 1M tokens threshold for multisig

    // Events
    event CategorySet(string indexed category, address indexed wallet, uint256 allocation);
    event CategoryRemoved(string indexed category);
    event TransferExecuted(address indexed to, uint256 amount, string reason, string category);
    event MultisigTransferExecuted(address indexed to, uint256 amount, string reason, string category);
    event TokensMinted(address indexed to, uint256 amount, string reason);
    event TokensBurned(uint256 amount, string reason);
    event MultisigUpdated(address indexed oldMultisig, address indexed newMultisig);
    event EmergencyWithdrawal(address indexed token, address indexed to, uint256 amount);

    // Modifiers
    modifier onlyMultisig() {
        require(msg.sender == address(multisig), "Treasury: Only multisig can call this");
        _;
    }

    modifier categoryExistsModifier(string memory category) {
        require(categoryExists[category], "Treasury: Category does not exist");
        _;
    }

    /**
     * @dev Constructor
     * @param _nyax NYAX token address
     * @param _multisig MultiSig wallet address
     * @param _owner Treasury owner address
     */
    constructor(
        address _nyax,
        address _multisig,
        address _owner
    ) Ownable(_owner) {
        require(_nyax != address(0), "Treasury: Invalid NYAX address");
        require(_multisig != address(0), "Treasury: Invalid multisig address");
        require(_owner != address(0), "Treasury: Invalid owner address");

        nyax = NYAXToken(_nyax);
        multisig = SimpleMultiSig(payable(_multisig));
    }

    /**
     * @dev Set category wallet and allocation
     * @param category Category name
     * @param wallet Wallet address for the category
     * @param allocation Allocation percentage in basis points (e.g., 2000 = 20%)
     */
    function setCategoryWallet(
        string calldata category,
        address wallet,
        uint256 allocation
    ) external onlyOwner {
        require(wallet != address(0), "Treasury: Invalid wallet address");
        require(allocation <= BASIS_POINTS, "Treasury: Allocation exceeds 100%");
        require(bytes(category).length > 0, "Treasury: Category cannot be empty");

        // Add to categories array if new
        if (!categoryExists[category]) {
            categories.push(category);
            categoryExists[category] = true;
        }

        categoryWallet[category] = wallet;
        categoryAllocation[category] = allocation;

        emit CategorySet(category, wallet, allocation);
    }

    /**
     * @dev Remove a category
     * @param category Category name to remove
     */
    function removeCategory(string calldata category) external onlyOwner categoryExistsModifier(category) {
        require(categoryDistributed[category] == 0, "Treasury: Cannot remove category with distributions");

        delete categoryWallet[category];
        delete categoryAllocation[category];
        delete categoryDistributed[category];
        categoryExists[category] = false;

        // Remove from categories array
        for (uint256 i = 0; i < categories.length; i++) {
            if (keccak256(bytes(categories[i])) == keccak256(bytes(category))) {
                categories[i] = categories[categories.length - 1];
                categories.pop();
                break;
            }
        }

        emit CategoryRemoved(category);
    }

    /**
     * @dev Direct transfer for small amounts (owner only)
     * @param to Recipient address
     * @param amount Amount to transfer
     * @param reason Reason for transfer
     * @param category Category for tracking
     */
    function transferTo(
        address to,
        uint256 amount,
        string calldata reason,
        string calldata category
    ) external onlyOwner nonReentrant {
        require(to != address(0), "Treasury: Invalid recipient");
        require(amount > 0, "Treasury: Amount must be greater than 0");
        require(amount < MULTISIG_THRESHOLD, "Treasury: Amount exceeds multisig threshold");
        require(nyax.balanceOf(address(this)) >= amount, "Treasury: Insufficient treasury balance");

        // Update category tracking if category exists
        if (categoryExists[category]) {
            categoryDistributed[category] += amount;
        }

        IERC20(address(nyax)).safeTransfer(to, amount);
        emit TransferExecuted(to, amount, reason, category);
    }

    /**
     * @dev Multisig transfer for large amounts
     * @param to Recipient address
     * @param amount Amount to transfer
     * @param reason Reason for transfer
     * @param category Category for tracking
     */
    function multisigTransfer(
        address to,
        uint256 amount,
        string calldata reason,
        string calldata category
    ) external onlyMultisig nonReentrant {
        require(to != address(0), "Treasury: Invalid recipient");
        require(amount > 0, "Treasury: Amount must be greater than 0");
        require(nyax.balanceOf(address(this)) >= amount, "Treasury: Insufficient treasury balance");

        // Update category tracking if category exists
        if (categoryExists[category]) {
            categoryDistributed[category] += amount;
        }

        IERC20(address(nyax)).safeTransfer(to, amount);
        emit MultisigTransferExecuted(to, amount, reason, category);
    }

    /**
     * @dev Mint tokens to treasury
     * @param amount Amount to mint
     * @param reason Reason for minting
     */
    function mintToTreasury(uint256 amount, string calldata reason) external onlyOwner {
        require(amount > 0, "Treasury: Amount must be greater than 0");

        nyax.mint(address(this), amount);
        emit TokensMinted(address(this), amount, reason);
    }

    /**
     * @dev Mint tokens to specific address
     * @param to Recipient address
     * @param amount Amount to mint
     * @param reason Reason for minting
     * @param category Category for tracking
     */
    function mintTo(
        address to,
        uint256 amount,
        string calldata reason,
        string calldata category
    ) external onlyOwner {
        require(to != address(0), "Treasury: Invalid recipient");
        require(amount > 0, "Treasury: Amount must be greater than 0");

        // Update category tracking if category exists
        if (categoryExists[category]) {
            categoryDistributed[category] += amount;
        }

        nyax.mint(to, amount);
        emit TokensMinted(to, amount, reason);
    }

    /**
     * @dev Burn tokens from treasury
     * @param amount Amount to burn
     * @param reason Reason for burning
     */
    function burnFromTreasury(uint256 amount, string calldata reason) external onlyOwner {
        require(amount > 0, "Treasury: Amount must be greater than 0");
        require(nyax.balanceOf(address(this)) >= amount, "Treasury: Insufficient treasury balance");

        nyax.burn(address(this), amount);
        emit TokensBurned(amount, reason);
    }

    /**
     * @dev Update multisig address
     * @param _multisig New multisig address
     */
    function setMultisig(address _multisig) external onlyOwner {
        require(_multisig != address(0), "Treasury: Invalid multisig address");
        address oldMultisig = address(multisig);
        multisig = SimpleMultiSig(payable(_multisig));
        emit MultisigUpdated(oldMultisig, _multisig);
    }

    /**
     * @dev Get category information
     * @param category Category name
     * @return wallet Category wallet address
     * @return allocation Category allocation in basis points
     * @return distributed Amount already distributed
     * @return remaining Remaining allocation amount
     */
    function getCategoryInfo(string calldata category)
        external
        view
        categoryExistsModifier(category)
        returns (
            address wallet,
            uint256 allocation,
            uint256 distributed,
            uint256 remaining
        )
    {
        wallet = categoryWallet[category];
        allocation = categoryAllocation[category];
        distributed = categoryDistributed[category];

        uint256 totalSupply = nyax.totalSupply();
        uint256 maxAllocation = (totalSupply * allocation) / BASIS_POINTS;
        remaining = maxAllocation > distributed ? maxAllocation - distributed : 0;
    }

    /**
     * @dev Get all categories
     * @return Array of category names
     */
    function getCategories() external view returns (string[] memory) {
        return categories;
    }

    /**
     * @dev Get treasury balance
     * @return NYAX token balance of treasury
     */
    function getTreasuryBalance() external view returns (uint256) {
        return nyax.balanceOf(address(this));
    }

    /**
     * @dev Get total allocated percentage
     * @return Total allocation in basis points
     */
    function getTotalAllocation() external view returns (uint256) {
        uint256 total = 0;
        for (uint256 i = 0; i < categories.length; i++) {
            total += categoryAllocation[categories[i]];
        }
        return total;
    }

    /**
     * @dev Check if amount requires multisig approval
     * @param amount Amount to check
     * @return Whether multisig approval is required
     */
    function requiresMultisig(uint256 amount) external pure returns (bool) {
        return amount >= MULTISIG_THRESHOLD;
    }

    /**
     * @dev Emergency function to recover accidentally sent ERC20 tokens
     * @param token Token address to recover
     * @param amount Amount to recover
     */
    function emergencyRecoverERC20(address token, uint256 amount) external onlyOwner {
        require(token != address(nyax), "Treasury: Cannot recover NYAX tokens");
        require(token != address(0), "Treasury: Invalid token address");

        IERC20(token).safeTransfer(owner(), amount);
        emit EmergencyWithdrawal(token, owner(), amount);
    }

    /**
     * @dev Emergency function to recover accidentally sent ETH
     */
    function emergencyRecoverETH() external onlyOwner {
        uint256 balance = address(this).balance;
        require(balance > 0, "Treasury: No ETH to recover");

        payable(owner()).transfer(balance);
        emit EmergencyWithdrawal(address(0), owner(), balance);
    }

    /**
     * @dev Receive function to accept ETH (for emergency recovery)
     */
    receive() external payable {}
}

contracts/VestingFactory.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./VestingWalletFlexible.sol";

/**
 * @title VestingFactory
 * @dev Factory contract for creating and managing multiple vesting contracts
 * 
 * Features:
 * - Deploy new vesting contracts
 * - Track all deployed contracts
 * - Batch operations
 * - Category-based organization
 */
contract VestingFactory is Ownable, ReentrancyGuard {
    // State variables
    address public immutable nyaxToken;

    mapping(string => address[]) public categoryVestingContracts; // category => contracts
    mapping(address => bool) public isVestingContract;
    mapping(address => string) public contractCategory;

    address[] public allVestingContracts;
    string[] public categories;
    mapping(string => bool) public categoryExists;

    // Events
    event VestingContractCreated(
        address indexed vestingContract,
        string indexed category,
        address indexed creator
    );
    event CategoryAdded(string indexed category);

    /**
     * @dev Constructor
     * @param _nyaxToken NYAX token address
     * @param _owner Factory owner address
     */
    constructor(address _nyaxToken, address _owner) Ownable(_owner) {
        require(_nyaxToken != address(0), "VestingFactory: Invalid token address");
        require(_owner != address(0), "VestingFactory: Invalid owner address");

        nyaxToken = _nyaxToken;
    }

    /**
     * @dev Create a new vesting contract
     * @param category Category for the vesting contract
     * @return vestingContract Address of the created vesting contract
     */
    function createVestingContract(string memory category) 
        external 
        onlyOwner 
        returns (address vestingContract) 
    {
        require(bytes(category).length > 0, "VestingFactory: Category cannot be empty");

        // Add category if it doesn't exist
        if (!categoryExists[category]) {
            categories.push(category);
            categoryExists[category] = true;
            emit CategoryAdded(category);
        }

        // Deploy new vesting contract
        VestingWalletFlexible newVesting = new VestingWalletFlexible(nyaxToken, owner());
        vestingContract = address(newVesting);

        // Track the contract
        allVestingContracts.push(vestingContract);
        categoryVestingContracts[category].push(vestingContract);
        isVestingContract[vestingContract] = true;
        contractCategory[vestingContract] = category;

        emit VestingContractCreated(vestingContract, category, msg.sender);

        return vestingContract;
    }

    /**
     * @dev Get all vesting contracts for a category
     * @param category Category name
     * @return Array of vesting contract addresses
     */
    function getCategoryContracts(string memory category) 
        external 
        view 
        returns (address[] memory) 
    {
        return categoryVestingContracts[category];
    }

    /**
     * @dev Get all vesting contracts
     * @return Array of all vesting contract addresses
     */
    function getAllContracts() external view returns (address[] memory) {
        return allVestingContracts;
    }

    /**
     * @dev Get all categories
     * @return Array of category names
     */
    function getCategories() external view returns (string[] memory) {
        return categories;
    }

    /**
     * @dev Get contract count for a category
     * @param category Category name
     * @return Number of contracts in category
     */
    function getCategoryContractCount(string memory category) 
        external 
        view 
        returns (uint256) 
    {
        return categoryVestingContracts[category].length;
    }

    /**
     * @dev Get total contract count
     * @return Total number of vesting contracts
     */
    function getTotalContractCount() external view returns (uint256) {
        return allVestingContracts.length;
    }

    /**
     * @dev Check if address is a vesting contract created by this factory
     * @param contractAddress Address to check
     * @return Whether address is a vesting contract
     */
    function isFactoryContract(address contractAddress) external view returns (bool) {
        return isVestingContract[contractAddress];
    }

    /**
     * @dev Get category for a contract
     * @param contractAddress Vesting contract address
     * @return Category name
     */
    function getContractCategory(address contractAddress) 
        external 
        view 
        returns (string memory) 
    {
        require(isVestingContract[contractAddress], "VestingFactory: Not a factory contract");
        return contractCategory[contractAddress];
    }
}

contracts/VestingWalletFlexible.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.24;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title VestingWalletFlexible
 * @dev Flexible vesting contract for NYAX tokens
 * 
 * Features:
 * - Cliff period support
 * - Linear vesting after cliff
 * - Milestone-based releases
 * - Revocable vesting (optional)
 * - Emergency pause functionality
 * - Multiple beneficiaries support
 */
contract VestingWalletFlexible is ReentrancyGuard, Ownable {
    using SafeERC20 for IERC20;

    // Structs
    struct VestingSchedule {
        address beneficiary;
        uint256 totalAmount;
        uint256 start;
        uint256 cliff;
        uint256 duration;
        uint256 released;
        bool revoked;
        bool revocable;
        string category; // e.g., "team", "advisors", "marketing"
    }

    struct Milestone {
        uint256 timestamp;
        uint256 percentage; // In basis points (10000 = 100%)
        bool released;
        string description;
    }

    // State variables
    IERC20 public immutable token;
    uint256 public constant BASIS_POINTS = 10000;

    mapping(bytes32 => VestingSchedule) public vestingSchedules;
    mapping(bytes32 => Milestone[]) public milestones;
    mapping(address => bytes32[]) public beneficiarySchedules;

    bytes32[] public allScheduleIds;
    bool public paused = false;

    // Events
    event VestingScheduleCreated(
        bytes32 indexed scheduleId,
        address indexed beneficiary,
        uint256 totalAmount,
        uint256 start,
        uint256 cliff,
        uint256 duration,
        string category
    );
    event TokensReleased(bytes32 indexed scheduleId, address indexed beneficiary, uint256 amount);
    event VestingRevoked(bytes32 indexed scheduleId, address indexed beneficiary, uint256 unreleased);
    event MilestoneAdded(bytes32 indexed scheduleId, uint256 timestamp, uint256 percentage, string description);
    event MilestoneReleased(bytes32 indexed scheduleId, uint256 amount, string description);
    event PauseToggled(bool paused);
    event EmergencyWithdrawal(address indexed token, uint256 amount);

    // Modifiers
    modifier whenNotPaused() {
        require(!paused, "VestingWallet: Contract is paused");
        _;
    }

    modifier validSchedule(bytes32 scheduleId) {
        require(vestingSchedules[scheduleId].beneficiary != address(0), "VestingWallet: Invalid schedule");
        _;
    }

    /**
     * @dev Constructor
     * @param _token NYAX token address
     * @param _owner Contract owner address
     */
    constructor(address _token, address _owner) Ownable(_owner) {
        require(_token != address(0), "VestingWallet: Invalid token address");
        require(_owner != address(0), "VestingWallet: Invalid owner address");

        token = IERC20(_token);
    }

    /**
     * @dev Create a new vesting schedule
     * @param beneficiary Address of the beneficiary
     * @param totalAmount Total amount of tokens to vest
     * @param start Start timestamp
     * @param cliffDuration Cliff duration in seconds
     * @param duration Total vesting duration in seconds
     * @param revocable Whether the vesting is revocable
     * @param category Category of the vesting (e.g., "team", "advisors")
     * @return scheduleId Unique identifier for the vesting schedule
     */
    function createVestingSchedule(
        address beneficiary,
        uint256 totalAmount,
        uint256 start,
        uint256 cliffDuration,
        uint256 duration,
        bool revocable,
        string memory category
    ) external onlyOwner returns (bytes32 scheduleId) {
        require(beneficiary != address(0), "VestingWallet: Invalid beneficiary");
        require(totalAmount > 0, "VestingWallet: Amount must be greater than 0");
        require(duration > 0, "VestingWallet: Duration must be greater than 0");
        require(cliffDuration <= duration, "VestingWallet: Cliff cannot exceed duration");
        require(start > 0, "VestingWallet: Start time must be set");

        scheduleId = keccak256(abi.encodePacked(beneficiary, totalAmount, start, block.timestamp));

        require(vestingSchedules[scheduleId].beneficiary == address(0), "VestingWallet: Schedule already exists");

        vestingSchedules[scheduleId] = VestingSchedule({
            beneficiary: beneficiary,
            totalAmount: totalAmount,
            start: start,
            cliff: start + cliffDuration,
            duration: duration,
            released: 0,
            revoked: false,
            revocable: revocable,
            category: category
        });

        beneficiarySchedules[beneficiary].push(scheduleId);
        allScheduleIds.push(scheduleId);

        // Transfer tokens to this contract
        token.safeTransferFrom(msg.sender, address(this), totalAmount);

        emit VestingScheduleCreated(
            scheduleId,
            beneficiary,
            totalAmount,
            start,
            start + cliffDuration,
            duration,
            category
        );

        return scheduleId;
    }

    /**
     * @dev Add milestone to a vesting schedule
     * @param scheduleId Vesting schedule ID
     * @param timestamp Milestone timestamp
     * @param percentage Percentage to release at milestone (basis points)
     * @param description Milestone description
     */
    function addMilestone(
        bytes32 scheduleId,
        uint256 timestamp,
        uint256 percentage,
        string memory description
    ) external onlyOwner validSchedule(scheduleId) {
        require(timestamp > block.timestamp, "VestingWallet: Milestone must be in future");
        require(percentage <= BASIS_POINTS, "VestingWallet: Percentage exceeds 100%");
        require(bytes(description).length > 0, "VestingWallet: Description required");

        milestones[scheduleId].push(Milestone({
            timestamp: timestamp,
            percentage: percentage,
            released: false,
            description: description
        }));

        emit MilestoneAdded(scheduleId, timestamp, percentage, description);
    }

    /**
     * @dev Calculate vested amount for a schedule at given time
     * @param scheduleId Vesting schedule ID
     * @param timestamp Time to calculate vesting for
     * @return Vested amount
     */
    function vestedAmount(bytes32 scheduleId, uint256 timestamp) 
        public 
        view 
        validSchedule(scheduleId) 
        returns (uint256) 
    {
        VestingSchedule memory schedule = vestingSchedules[scheduleId];

        if (schedule.revoked) {
            return schedule.released;
        }

        if (timestamp < schedule.cliff) {
            return 0;
        }

        // Check milestones first
        uint256 milestoneVested = getMilestoneVested(scheduleId, timestamp);
        if (milestoneVested > 0) {
            return milestoneVested;
        }

        // Linear vesting after cliff
        if (timestamp >= schedule.start + schedule.duration) {
            return schedule.totalAmount;
        }

        uint256 elapsed = timestamp - schedule.start;
        return (schedule.totalAmount * elapsed) / schedule.duration;
    }

    /**
     * @dev Get milestone vested amount
     * @param scheduleId Vesting schedule ID
     * @param timestamp Current timestamp
     * @return Milestone vested amount
     */
    function getMilestoneVested(bytes32 scheduleId, uint256 timestamp) 
        public 
        view 
        returns (uint256) 
    {
        VestingSchedule memory schedule = vestingSchedules[scheduleId];
        Milestone[] memory scheduleMilestones = milestones[scheduleId];

        if (scheduleMilestones.length == 0) {
            return 0;
        }

        uint256 totalMilestonePercentage = 0;
        for (uint256 i = 0; i < scheduleMilestones.length; i++) {
            if (timestamp >= scheduleMilestones[i].timestamp) {
                totalMilestonePercentage += scheduleMilestones[i].percentage;
            }
        }

        return (schedule.totalAmount * totalMilestonePercentage) / BASIS_POINTS;
    }

    /**
     * @dev Release vested tokens for a schedule
     * @param scheduleId Vesting schedule ID
     */
    function release(bytes32 scheduleId) 
        external 
        nonReentrant 
        whenNotPaused 
        validSchedule(scheduleId) 
    {
        VestingSchedule storage schedule = vestingSchedules[scheduleId];
        require(
            msg.sender == schedule.beneficiary || msg.sender == owner(),
            "VestingWallet: Not authorized"
        );

        uint256 vested = vestedAmount(scheduleId, block.timestamp);
        uint256 unreleased = vested - schedule.released;
        require(unreleased > 0, "VestingWallet: No tokens to release");

        schedule.released += unreleased;
        token.safeTransfer(schedule.beneficiary, unreleased);

        // Mark milestones as released
        _markMilestonesReleased(scheduleId);

        emit TokensReleased(scheduleId, schedule.beneficiary, unreleased);
    }

    /**
     * @dev Revoke a vesting schedule
     * @param scheduleId Vesting schedule ID
     */
    function revoke(bytes32 scheduleId) 
        external 
        onlyOwner 
        validSchedule(scheduleId) 
    {
        VestingSchedule storage schedule = vestingSchedules[scheduleId];
        require(schedule.revocable, "VestingWallet: Not revocable");
        require(!schedule.revoked, "VestingWallet: Already revoked");

        uint256 vested = vestedAmount(scheduleId, block.timestamp);
        uint256 unreleased = vested - schedule.released;
        uint256 refund = schedule.totalAmount - vested;

        schedule.revoked = true;

        if (unreleased > 0) {
            schedule.released += unreleased;
            token.safeTransfer(schedule.beneficiary, unreleased);
        }

        if (refund > 0) {
            token.safeTransfer(owner(), refund);
        }

        emit VestingRevoked(scheduleId, schedule.beneficiary, refund);
    }

    /**
     * @dev Mark milestones as released
     * @param scheduleId Vesting schedule ID
     */
    function _markMilestonesReleased(bytes32 scheduleId) internal {
        Milestone[] storage scheduleMilestones = milestones[scheduleId];

        for (uint256 i = 0; i < scheduleMilestones.length; i++) {
            if (block.timestamp >= scheduleMilestones[i].timestamp && !scheduleMilestones[i].released) {
                scheduleMilestones[i].released = true;

                VestingSchedule memory schedule = vestingSchedules[scheduleId];
                uint256 milestoneAmount = (schedule.totalAmount * scheduleMilestones[i].percentage) / BASIS_POINTS;

                emit MilestoneReleased(scheduleId, milestoneAmount, scheduleMilestones[i].description);
            }
        }
    }

    /**
     * @dev Get releasable amount for a schedule
     * @param scheduleId Vesting schedule ID
     * @return Releasable amount
     */
    function releasableAmount(bytes32 scheduleId) 
        external 
        view 
        validSchedule(scheduleId) 
        returns (uint256) 
    {
        uint256 vested = vestedAmount(scheduleId, block.timestamp);
        return vested - vestingSchedules[scheduleId].released;
    }

    /**
     * @dev Get beneficiary's schedule IDs
     * @param beneficiary Beneficiary address
     * @return Array of schedule IDs
     */
    function getBeneficiarySchedules(address beneficiary) 
        external 
        view 
        returns (bytes32[] memory) 
    {
        return beneficiarySchedules[beneficiary];
    }

    /**
     * @dev Get all schedule IDs
     * @return Array of all schedule IDs
     */
    function getAllSchedules() external view returns (bytes32[] memory) {
